<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import {weekRange,monthRange} from './blue/report-model.js';
import {reportModel,reportPages,fileName} from './dojo/resources.js';
import {renderDojo} from './dojo/report.js';
const props=defineProps({rows:Array,roles:Array,initialRole:String,initialDate:String}),emit=defineEmits(['close']);
const roleId=ref(props.initialRole||''),kind=ref('week'),date=ref(props.initialDate||new Date().toISOString().slice(0,10)),month=ref(date.value.slice(0,7)),includeDetail=ref(false),page=ref(1),image=ref(null),rendering=ref(false),saving=ref(false),error=ref(''),notice=ref('');let generation=0;
const choices=computed(()=>props.roles.filter(r=>r.selected||props.rows.some(m=>m.role_id===r.id)));
if(!roleId.value&&choices.value.length===1)roleId.value=choices.value[0].id;
const role=computed(()=>choices.value.find(r=>r.id===roleId.value));
const range=computed(()=>kind.value==='week'?weekRange(date.value):monthRange(month.value));
const model=computed(()=>role.value&&range.value?reportModel(props.rows,role.value,range.value.from,range.value.to):null);
const pages=computed(()=>model.value?reportPages(model.value,includeDetail.value):[]);
const imageKey=computed(()=>JSON.stringify([model.value,kind.value,includeDetail.value,page.value]));
const ready=computed(()=>image.value?.key===imageKey.value&&!rendering.value&&!saving.value&&!error.value);
function clear(){if(image.value)URL.revokeObjectURL(image.value.url);image.value=null;}
watch([roleId,kind,date,month,includeDetail],()=>{page.value=1;notice.value='';},{flush:'sync'});
watch(imageKey,async()=>{const token=++generation,key=imageKey.value;clear();error.value='';if(!model.value)return;rendering.value=true;try{const blob=await renderDojo(model.value,pages.value[page.value-1],page.value,pages.value.length,kind.value==='week'?'周报':'月报');if(token!==generation)return;image.value={blob,url:URL.createObjectURL(blob),key};}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation)rendering.value=false;}},{immediate:true});
async function download(){if(!ready.value)return;saving.value=true;notice.value='';try{let binary='';const bytes=new Uint8Array(await image.value.blob.arrayBuffer());for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const filename=fileName(role.value.label,kind.value==='week'?'周报':'月报',model.value.from,model.value.to,page.value,pages.value.length);const r=await window.pywebview.api.blue_export({kind:'png',filename,content:btoa(binary)});if(!r.ok)throw Error(r.error);notice.value=r.data.cancelled?'已取消保存':`已保存第 ${page.value} / ${pages.value.length} 张`;}catch(e){notice.value=e.message}finally{saving.value=false;}}
async function copy(){if(!ready.value)return;saving.value=true;try{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw Error();await navigator.clipboard.write([new ClipboardItem({'image/png':image.value.blob})]);notice.value='图片已复制';}catch{notice.value='复制不可用，请下载 PNG 后发送';}finally{saving.value=false;}}
function canLeave(){return !saving.value}defineExpose({canLeave});onUnmounted(()=>{generation++;clear()});
</script>
<template><Teleport to="body"><div class="dojo-report-mask"><section class="dojo-report" role="dialog" aria-modal="true" aria-label="导出道馆周报月报"><header><div><h2>道馆周报 / 月报</h2><p>按角色生成完整周期资源合计，结界卡分星级；不受页面资源筛选或分页影响。</p></div><button @click="emit('close')" :disabled="saving" aria-label="关闭道馆报表">×</button></header><main><div class="report-fields"><label>角色<select aria-label="报表角色" v-model="roleId" :disabled="saving"><option value="">请选择角色</option><option v-for="r in choices" :key="r.id" :value="r.id">{{r.label}} · {{r.server}}</option></select></label><label>周期<select aria-label="报表周期" v-model="kind" :disabled="saving"><option value="week">周报</option><option value="month">月报</option></select></label><label v-if="kind==='week'">本周内任意日期<input type="date" aria-label="报表周日期" v-model="date" :disabled="saving"></label><label v-else>月份<input type="month" aria-label="报表月份" v-model="month" :disabled="saving"></label></div><label class="report-detail-toggle"><input type="checkbox" v-model="includeDetail" :disabled="saving">附每日资源明细（小图标逐场明细，导出长图）</label><p v-if="!role">先选择委托人的角色。</p><p v-else-if="model">{{model.from}} — {{model.to}} · {{model.mailCount}} 封邮件 · {{model.totals.length}} 种资源</p><p v-if="error" role="alert">{{error}}</p><p v-if="rendering">正在生成高清图片…</p><img v-if="image" :src="image.url" alt="道馆产出报表预览"><nav v-if="pages.length>1"><button @click="page--" :disabled="page<=1||saving">上一张</button><span>第 {{page}} / {{pages.length}} 张</span><button @click="page++" :disabled="page>=pages.length||saving">下一张</button></nav><p role="status">{{notice}}</p></main><footer><small>PNG · {{includeDetail?'邮件长图 · 尺寸自动适配':'2160 像素宽'}} · 不包含内部 ID 或账号凭证</small><button @click="copy" :disabled="!ready">复制图片</button><button class="primary" @click="download" :disabled="!ready">{{saving?'保存中…':includeDetail?'下载完整长图':pages.length>1?'下载 PNG（当前张）':'下载 PNG'}}</button></footer></section></div></Teleport></template>
<style scoped>
.dojo-report-mask{position:fixed;inset:0;z-index:2200;background:#2c241b70;display:grid;place-items:center;padding:24px;font:14px/1.6 "Microsoft YaHei UI","Microsoft YaHei",sans-serif;color:#4a4033}.dojo-report{display:flex;flex-direction:column;background:#fffcf5;border:1px solid #dfcdb2;border-radius:12px;width:min(100%,1050px);max-height:calc(100dvh - 48px);overflow:hidden}.dojo-report header{display:flex;justify-content:space-between;gap:16px;padding:20px 24px;border-bottom:1px solid #e4d5c0}.dojo-report h2{font-size:23px;margin:0}.dojo-report p{margin:7px 0;color:#7e6c51;font-size:13px}.dojo-report main{padding:18px 24px;overflow:auto;min-height:0}.report-fields{display:grid;grid-template-columns:2fr 1fr 1.5fr;gap:14px}.report-fields label{display:flex;flex-direction:column;gap:6px}.report-fields input,.report-fields select{font:inherit;border:1px solid #d7c3a4;border-radius:5px;background:#fffdf9;padding:8px;min-width:0}.report-detail-toggle{display:flex;align-items:center;gap:7px;margin:15px 0}.dojo-report img{display:block;width:min(100%,640px);height:auto;margin:16px auto;border:1px solid #e0d0b5;box-shadow:0 8px 24px #705b3820}.dojo-report nav{display:flex;justify-content:center;align-items:center;gap:12px}.dojo-report footer{display:flex;align-items:center;gap:10px;padding:15px 24px;border-top:1px solid #e4d5c0}.dojo-report footer small{margin-right:auto;font-size:12px;color:#8a7759}.dojo-report button{font:inherit;border:1px solid #d8c3a3;border-radius:5px;padding:8px 12px;background:#f4eadb;color:#6b5132;cursor:pointer}.dojo-report button.primary{background:#745b40;color:white}.dojo-report button:disabled{opacity:.5;cursor:default}@media(max-width:700px){.report-fields{grid-template-columns:1fr}.dojo-report footer{flex-wrap:wrap}}
</style>
